from __future__ import annotations

from datetime import datetime
from typing import List, Optional
from pydantic import BaseModel, Field


class User(BaseModel):
    """Represents a user registered in the ZKTeco device."""

    uid: int = Field(description="Internal sequential UID used by the hardware")
    user_id: str = Field(
        description="External user identifier (badge / registration ID)"
    )
    name: str = Field(default="", description="User full name (typically max 24 chars)")
    privilege: int = Field(
        default=0, description="Privilege level: 0=User, 14=Admin, etc."
    )
    password: str = Field(default="", description="Numeric PIN / password")
    card: int = Field(default=0, description="RFID / Wiegand card number (0 = no card)")
    group_id: str = Field(
        default="", description="Native department / group ID on the device"
    )


class FingerprintTemplate(BaseModel):
    """Represents a biometric fingerprint template on the device."""

    uid: int = Field(description="Internal hardware UID of the user")
    fid: int = Field(default=0, description="Finger index (0 to 9)")
    size: int = Field(default=0, description="Template buffer size in bytes")
    valid: int = Field(default=1, description="Validity flag (1 = valid)")
    template: str = Field(default="", description="Raw template string or base64 data")


class AttendanceRecord(BaseModel):
    """Represents an attendance / access log record from the device."""

    user_id: str = Field(description="User ID associated with the punch")
    timestamp: datetime = Field(description="Datetime when the access occurred")
    status: int = Field(default=0, description="Status code of the punch")
    punch: int = Field(
        default=0, description="Punch type (0=Check-in, 1=Check-out, etc.)"
    )
    uid: Optional[int] = Field(default=None, description="Hardware UID if present")


class NetworkParams(BaseModel):
    """Device network configuration parameters."""

    ip: Optional[str] = Field(default=None, description="IP Address")
    mask: Optional[str] = Field(default=None, description="Subnet Mask")
    gateway: Optional[str] = Field(default=None, description="Gateway Address")


class DeviceInfo(BaseModel):
    """Hardware and firmware metadata of the ZKTeco terminal."""

    firmware_version: Optional[str] = Field(
        default=None, description="Firmware version"
    )
    platform: Optional[str] = Field(
        default=None, description="Device hardware platform"
    )
    serial_number: Optional[str] = Field(
        default=None, description="Device serial number"
    )
    mac_address: Optional[str] = Field(default=None, description="MAC Address")
    device_name: Optional[str] = Field(
        default=None, description="Configured device name"
    )
    device_time: Optional[datetime] = Field(
        default=None, description="Current time on the device"
    )
    pin_width: Optional[int] = Field(
        default=None, description="PIN width configuration"
    )
    fp_version: Optional[str] = Field(
        default=None, description="Fingerprint algorithm version (e.g. ZKFinger 10.0)"
    )
    face_version: Optional[str] = Field(
        default=None, description="Face recognition algorithm version"
    )
    network: Optional[NetworkParams] = Field(
        default=None, description="Network parameters"
    )


class CapacityInfo(BaseModel):
    """Memory usage and capacity metrics of the device."""

    users: Optional[int] = Field(default=None, description="Registered users count")
    users_cap: Optional[int] = Field(default=None, description="Maximum users capacity")
    fingers: Optional[int] = Field(
        default=None, description="Registered fingerprints count"
    )
    fingers_cap: Optional[int] = Field(
        default=None, description="Maximum fingerprints capacity"
    )
    records: Optional[int] = Field(
        default=None, description="Stored attendance logs count"
    )
    records_cap: Optional[int] = Field(
        default=None, description="Maximum attendance logs capacity"
    )


class TimeWindow(BaseModel):
    """A time interval window within a TimeZone rule.

    weekday: 0=Monday ... 6=Sunday (standard datetime.weekday()); None means all days.
    start / end: Time strings in 'HH:MM' 24-hour format.
    """

    weekday: Optional[int] = Field(
        default=None, ge=0, le=6, description="Day of week (0=Mon..6=Sun) or None"
    )
    start: str = Field(
        pattern=r"^\d{1,2}:\d{2}$", description="Start time in HH:MM format"
    )
    end: str = Field(pattern=r"^\d{1,2}:\d{2}$", description="End time in HH:MM format")

    def allows(self, when: datetime) -> bool:
        if self.weekday is not None and when.weekday() != self.weekday:
            return False
        start_h, start_m = map(int, self.start.split(":"))
        end_h, end_m = map(int, self.end.split(":"))
        start_minutes = start_h * 60 + start_m
        end_minutes = end_h * 60 + end_m
        now_minutes = when.hour * 60 + when.minute
        return start_minutes <= now_minutes <= end_minutes


class TimeZoneRule(BaseModel):
    """Named set of allowed time windows (e.g. 'Business Hours')."""

    name: str = Field(description="Name of the time zone rule")
    windows: List[TimeWindow] = Field(
        default_factory=list, description="List of allowed time windows"
    )

    def is_allowed(self, when: datetime) -> bool:
        if not self.windows:
            return True
        return any(w.allows(when) for w in self.windows)


class Area(BaseModel):
    """Logical area definition associated with a time zone rule."""

    name: str = Field(description="Area name (e.g. 'Data Center', 'Front Desk')")
    time_zone: Optional[str] = Field(
        default=None, description="Associated TimeZoneRule name"
    )
    description: str = Field(default="", description="Optional description")


class LiveAccessEvent(BaseModel):
    """Represents a real-time event received during live capture."""

    attendance: AttendanceRecord = Field(description="Raw attendance record")
    allowed: Optional[bool] = Field(
        default=None, description="Rule evaluation result if enforced"
    )
    area_name: Optional[str] = Field(
        default=None, description="Logical area name for the user"
    )
    verdict: Optional[str] = Field(
        default=None, description="Human readable verdict (e.g. OK or ACCESS_DENIED)"
    )
